<script type ="text/javascript">

function limpiaForm(formSelector, excludeSelector)
{
    var $form = jQuery(formSelector);
    var excludedValues = {};
    
    // Guardar valores de campos a excluir
    jQuery(excludeSelector).each(function() {
        excludedValues[this.id || this.name] = jQuery(this).val();
    });
    
    // Resetear formulario
    $form[0].reset();
    
    // Restaurar valores excluidos
    jQuery(excludeSelector).each(function() {
        var key = this.id || this.name;
        if (excludedValues[key] !== undefined) {
            jQuery(this).val(excludedValues[key]);
        }
    });
}

jQuery(document).ready(function() 
{
    // Cuando cambia el select del módulo
    jQuery('#el_modulo').change(function() 
    {
        // Ocultamos todos los campos dinámicos primero
        jQuery('.campo_dinamico').hide();
        jQuery('#to_hide_layer').hide();
        jQuery('#to_show_layer').css("display", "block");
        jQuery('#to_hide_layer2').hide();
        jQuery('#to_show_layer2').css("display", "block");
        
        // Obtenemos el valor seleccionado
        const valorSeleccionado = jQuery(this).val();

        if(valorSeleccionado != ''){
            limpiaForm('#form1', '#'+jQuery(this).attr('id'));
        }

        jQuery('#btn_enviar').show();
        jQuery('#btn_reset').show();
        
        // Mostramos los campos correspondientes según la opción seleccionada
        if (valorSeleccionado === '<?php echo ModulesEnable::Archivo; ?>') 
        {
            // Unidad Documental 1
            jQuery('#campos_opcion_1').show();
        } 
        else if (valorSeleccionado === '<?php echo ModulesEnable::ComEnviada; ?>') 
        {
            // Comunicaciones Enviadas 2
            jQuery('#campos_opcion_2').show();
        } 
        else if (valorSeleccionado === '<?php echo ModulesEnable::ComRecibida; ?>') 
        {
            // Comunicaciones Recibidas 3
            jQuery('#campos_opcion_3').show();
        } 
        else if (valorSeleccionado === '<?php echo ModulesEnable::ComInterna; ?>') 
        {
            // Comunicaciones Internas 4
            jQuery('#campos_opcion_4').show();
        }
        else if (valorSeleccionado === 'x') 
        {
            // Transferencias
            jQuery('#campos_opcion_5').show();
        }
        else if (valorSeleccionado === 'xx') 
        {
            // Servicios
            jQuery('#campos_opcion_6').show();
        }
        else if (valorSeleccionado === 'xxx') 
        {
            // Prestamos
            jQuery('#campos_opcion_7').show();
        }
        else 
        {
            // Si no se selecciona ninguna opción válida, ocultamos el botón enviar
            jQuery('#btn_enviar').hide();
            jQuery('#btn_reset').hide();
        }
    });
    
    // Al cargar la página, aseguramos que todos los campos estén ocultos inicialmente
    jQuery('.campo_dinamico').hide();
    jQuery('#btn_enviar').hide();
    jQuery('#btn_reset').hide();
    
    // Evitar el envío del formulario si no hay selección
    jQuery('#formulario-dinamico').submit(function(event) 
    {
        if (jQuery('#el_modulo').val() === '') 
        {
            event.preventDefault();
            alert('Por favor, seleccione un módulo antes de enviar el formulario.');
        }
    });
});
</script>